# -*- coding: utf-8 -*-
"""MANAPRINT - Generateur BROWN 14 BOULES (A4 PAYSAGE, 12 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa nouvelle maquette BROWN (le cadre, << N deg ___ >>, le titre << BROWN >>,
   la fleur d'hibiscus, la ligne de colonnes B . I . N . G . O et les 14 cases
   arrondies - colonne centrale N a DEUX cases). RIEN n'a ete redessine :
   on ECRIT seulement les 14 numeros et le numero de serie.

LA REGLE DU JEU (inchangee) : 14 numeros tries par colonne -
   B 1-15 (x3) . I 16-30 (x3) . N 31-45 (x2, colonne centrale) .
   G 46-60 (x3) . O 61-75 (x3). Le crieur sort 1-75.
   Le numero de serie se pose sur la ligne << N deg ___ >> de l'en-tete.

L'ARC-EN-CIEL EST CARTON PAR CARTON. En N&B au gris #555555.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

try:
    pdfmetrics.registerFont(TTFont("DJLBRW", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
    POLICE = "DJLBRW"
except Exception:
    POLICE = "Helvetica"

RAINBOW = [
    "#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
    "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41",
]
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.80, 0.80, 0.80)

import os as _os
try:
    pdfmetrics.registerFont(TTFont("LMROMANBRW", _os.path.join(
        _os.path.dirname(_os.path.abspath(__file__)), "LatinModern.ttf")))
    _POLICE_ECO = "LMROMANBRW"
except Exception:
    try:
        pdfmetrics.registerFont(TTFont("DJLECOBRW", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
        _POLICE_ECO = "DJLECOBRW"
    except Exception:
        _POLICE_ECO = "Helvetica"
_GRIS_ECO = colors.Color(0.40, 0.40, 0.40)
_GRAS_TRAIT = 0.012
_POLICE_P15 = _POLICE_ECO
_GRIS_P15 = colors.Color(0.14, 0.14, 0.14)

TRAIT_NB = "#555555"


def _style_chiffres(style):
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO


# -- GEOMETRIE DE LA FEUILLE (A4 PAYSAGE, 4 colonnes x 3 rangees) --
PAGE_W, PAGE_H = landscape(A4)
ASPECT = 387.0 / 280.0
COLS_PAGE = 4
ROWS_PAGE = 3
CARTES_PAGE = COLS_PAGE * ROWS_PAGE
MARGE_X = 7 * mm
GUTTER_X = 4 * mm
GUTTER_Y = 4 * mm
CARD_W = (PAGE_W - 2 * MARGE_X - (COLS_PAGE - 1) * GUTTER_X) / COLS_PAGE
CARD_H = CARD_W / ASPECT
_BLOC_H = ROWS_PAGE * CARD_H + (ROWS_PAGE - 1) * GUTTER_Y
MARGE_TOP = (PAGE_H - _BLOC_H) / 2.0
MARGE_BOT = MARGE_TOP

# -- LES 5 COLONNES (fx depuis la gauche) et les RANGEES (fy depuis le HAUT) --
COLX = [0.114, 0.315, 0.505, 0.695, 0.896]   # B . I . N . G . O
ROWS_3 = [0.443, 0.646, 0.854]               # colonnes a 3 cases
ROWS_N = [0.507, 0.779]                       # colonne centrale N (2 cases)
# (min, max, nombre) par colonne - identique a l'ancien BROWN 14
COLONNES = [(1, 15, 3), (16, 30, 3), (31, 45, 2), (46, 60, 3), (61, 75, 3)]

TAILLE_CHIFFRE = 28.0
_T_SERIE = 7.0
_SERIE_FX = 0.217   # centre, sur la ligne << N deg ___ >>
_SERIE_FY = 0.121   # depuis le haut


def _graver_planche(c):
    nom = "BROWN14_DECOR"
    if not getattr(c, "_brown14_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H)
                else:
                    p.curveTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H,
                              v[2] / 1000.0 * CARD_W, CARD_H - v[3] / 1000.0 * CARD_H,
                              v[4] / 1000.0 * CARD_W, CARD_H - v[5] / 1000.0 * CARD_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._brown14_forme_faite = True
    return nom


def _poser_carton(c, x0, y0, couleur):
    nom = _graver_planche(c)
    c.saveState()
    c.setFillColor(couleur)
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_carte(rng):
    """14 numeros : 3 par colonne (2 pour N centrale), tries vers le bas."""
    return [sorted(rng.sample(range(pmin, pmax + 1), n)) for pmin, pmax, n in COLONNES]


def _tirer(rng, deja):
    g = None
    for _ in range(400):
        g = _gen_carte(rng)
        cle = tuple(tuple(x) for x in g)
        if cle not in deja:
            deja.add(cle)
            return g
    return g


def _dessiner_carton(c, x0, y0, cols_nums, serie, couleur, style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    _poser_carton(c, x0, y0, couleur)
    taille = TAILLE_CHIFFRE
    for ci, nums in enumerate(cols_nums):
        cx = x0 + CARD_W * COLX[ci]
        rows = ROWS_N if ci == 2 else ROWS_3
        for ri, val in enumerate(nums):
            fy = rows[ri]
            cy = y0 + CARD_H * (1.0 - fy) - taille * 0.36
            if _sec:
                _sec.chiffre_micro(c, val, cx, cy, taille, gris_ch, police_ch,
                                   epaisseur=_GRAS_TRAIT)
            else:
                c.setFillColor(gris_ch)
                c.setFont(police_ch, taille)
                c.drawCentredString(cx, cy, str(val))
    # numero de serie sur la ligne << N deg ___ >>
    c.setFillColor(GRIS)
    c.setFont(POLICE, _T_SERIE)
    c.drawCentredString(x0 + CARD_W * _SERIE_FX,
                        y0 + CARD_H * (1.0 - _SERIE_FY), "%06d" % serie)
    if _sec:
        try:
            _sec.cadre_micro(c, x0, y0, CARD_W, CARD_H, serie, retrait=0.9 * mm)
        except Exception:
            pass


def generer_pdf(nb_cartes=12, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="",
                page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)
    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE
    rng = random.Random(931400 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    faits = 0
    _deja = set()
    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 9)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 5.0 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 6)
        c.drawRightString(PAGE_W - MARGE_X, PAGE_H - 5.0 * mm, "%03d" % no_page)
        for row in range(ROWS_PAGE):
            for col_i in range(COLS_PAGE):
                if faits >= nb_cartes:
                    break
                x0 = MARGE_X + col_i * (CARD_W + GUTTER_X)
                y0 = MARGE_BOT + (ROWS_PAGE - 1 - row) * (CARD_H + GUTTER_Y)
                cols_nums = _tirer(rng, _deja)
                coul = colors.HexColor(
                    couleur_perso if (couleur and couleur_perso)
                    else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
                _dessiner_carton(c, x0, y0, cols_nums, serie, coul, style=style)
                serie += 1
                faits += 1
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


if __name__ == "__main__":
    with open("test_brown14.pdf", "wb") as f:
        f.write(generer_pdf(nb_cartes=12, couleur=True).read())
    print("BROWN 14 genere")


